// Opening names and book moves from Lichess's chess-openings data (CC0), matched by the
// sequence of moves from the starting position. Data: ./data/openings.json, generated by
// scripts/build-openings.ts. Transpositions into a named line by another move order are
// not recognised; the name stays at the last matching line.

export interface Opening {
  readonly eco: string;
  readonly name: string;
}

interface Node {
  opening?: Opening;
  readonly next: Map<string, Node>;
}

export class OpeningBook {
  readonly #root: Node = { next: new Map() };
  readonly size: number;

  constructor(lines: readonly (readonly [string, string, string])[]) {
    for (const [eco, name, moves] of lines) {
      let node = this.#root;
      for (const move of moves.split(' ')) {
        let child = node.next.get(move);
        if (!child) {
          child = { next: new Map() };
          node.next.set(move, child);
        }
        node = child;
      }
      node.opening = { eco, name };
    }
    this.size = lines.length;
  }

  /** The most specific named opening along `moves` (UCI from the standard start), or null. */
  name(moves: readonly string[]): Opening | null {
    let node: Node | undefined = this.#root;
    let found: Opening | null = null;
    for (const move of moves) {
      node = node.next.get(move);
      if (!node) break;
      if (node.opening) found = node.opening;
    }
    return found;
  }

  /** Book moves after `moves`, or an empty list once out of book. */
  continuations(moves: readonly string[]): string[] {
    let node: Node | undefined = this.#root;
    for (const move of moves) {
      node = node.next.get(move);
      if (!node) return [];
    }
    return [...node.next.keys()];
  }
}

let loading: Promise<OpeningBook> | null = null;

/** Load the bundled Lichess opening data on first use (a separate chunk in the build). */
export function loadOpeningBook(): Promise<OpeningBook> {
  loading ??= import('./data/openings.json', { with: { type: 'json' } }).then(
    (module) =>
      new OpeningBook((module.default as unknown as { lines: [string, string, string][] }).lines),
  );
  return loading;
}
